import { Component, Input } from '@angular/core';

@Component({
  selector: 'app-heavy-chart',
  template: `
    <div class="chart-host">
      <!-- Renders eagerly: the charting library is part of the
           initial bundle even though the chart may sit below
           the fold on mobile. -->
      <canvas #canvas></canvas>
    </div>
  `
})
export class HeavyChartComponent {
  @Input() data: number[] = [];
}

@Component({
  selector: 'app-dashboard',
  imports: [HeavyChartComponent],
  template: `
    <h1>Dashboard</h1>
    <section>
      <app-heavy-chart [data]="series" />
    </section>
  `
})
export class DashboardComponent {
  series = [1, 2, 3, 4, 5];
}

import { Component, Input } from '@angular/core';

@Component({
  selector: 'app-heavy-chart',
  template: `
    <div class="chart-host">
      <canvas #canvas></canvas>
    </div>
  `
})
export class HeavyChartComponent {
  @Input() data: number[] = [];
}

@Component({
  selector: 'app-dashboard',
  imports: [HeavyChartComponent],
  template: `
    <h1>Dashboard</h1>
    <section>
      @defer (on viewport) {
        <app-heavy-chart [data]="series" />
      } @placeholder {
        <div class="h-64 animate-pulse rounded bg-surface">
          Chart will appear here…
        </div>
      } @loading (minimum 300ms) {
        <p>Loading chart…</p>
      } @error {
        <p>Chart failed to load.</p>
      }
    </section>
  `
})
export class DashboardComponent {
  series = [1, 2, 3, 4, 5];
}
